def patch_part2_result_congratulations_obj(rom):
    """Redraw the Part 2 result screen's success title OBJ sheet in Korean."""
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    from PIL import Image, ImageDraw, ImageFont
    from lz77_compress import lz77_compress_optimal
    from lz77_scan import lz77_decompress

    off = 0xBFB45C
    dec = lz77_decompress(bytes(rom), off)
    if dec is None:
        raise AssertionError(f'invalid Part 2 result title LZ77 block at 0x{off:X}')
    data, consumed = dec
    if len(data) != 96 * 32:
        raise AssertionError(f'unexpected Part 2 result title size at 0x{off:X}: {len(data)}')

    font_path = require_font(OKDANDAN_FONT, 'OkDanDan')

    def draw_centered(img, text, max_size, fill, stroke_fill, shadow=None, stroke=1):
        draw = ImageDraw.Draw(img)
        box = (0, 0, img.width, img.height)
        for size in range(max_size, 7, -1):
            font = ImageFont.truetype(font_path, size)
            bbox = draw.textbbox((0, 0), text, font=font, stroke_width=stroke)
            if bbox[2] - bbox[0] <= img.width - 4 and bbox[3] - bbox[1] <= img.height - 2:
                break
        tw = bbox[2] - bbox[0]
        th = bbox[3] - bbox[1]
        x = box[0] + ((box[2] - box[0]) - tw) // 2 - bbox[0]
        y = box[1] + ((box[3] - box[1]) - th) // 2 - bbox[1]
        if shadow is not None:
            draw.text((x + 2, y + 2), text, font=font, fill=shadow, stroke_width=stroke, stroke_fill=stroke_fill)
        draw.text((x, y), text, font=font, fill=fill, stroke_width=stroke, stroke_fill=stroke_fill)

    # Runtime uses 1D OBJ mapping:
    # tiles 0..63: four 32x32 sprites for the large title at y=22
    # tiles 64..95: four 32x16 sprites for the small top title at y=3
    big = Image.new('P', (128, 32), 0)
    small = Image.new('P', (128, 16), 0)
    draw_centered(big, '작전 성공', 23, fill=1, stroke_fill=15, shadow=11, stroke=1)
    draw_centered(small, '축하합니다!', 14, fill=1, stroke_fill=9, shadow=11, stroke=1)

    out = bytearray(len(data))

    def copy_tile(img, src_x, src_y, tile_idx):
        px = img.load()
        base = tile_idx * 32
        for row in range(8):
            for col in range(8):
                value = px[src_x + col, src_y + row] & 0x0F
                bi = base + row * 4 + col // 2
                if col & 1:
                    out[bi] |= value << 4
                else:
                    out[bi] |= value

    for sprite in range(4):
        for ty in range(4):
            for tx in range(4):
                copy_tile(big, sprite * 32 + tx * 8, ty * 8, sprite * 16 + ty * 4 + tx)

    for sprite in range(4):
        for ty in range(2):
            for tx in range(4):
                copy_tile(small, sprite * 32 + tx * 8, ty * 8, 64 + sprite * 8 + ty * 4 + tx)

    comp = lz77_compress_optimal(bytes(out), vram_safe=True)
    if len(comp) > consumed:
        raise AssertionError(f'Part 2 result title LZ77 overflow: {len(comp)} > {consumed}')
    rom[off:off + consumed] = comp + bytes(consumed - len(comp))
    return 1


def patch_part2_air_mission_title_obj(rom):
    """Redraw the Part 2 "Sky" tutorial mission title OBJ sheet in Korean."""
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    from PIL import Image, ImageDraw, ImageFont
    from lz77_compress import lz77_compress_optimal
    from lz77_scan import lz77_decompress

    off = 0xC11D9C
    dec = lz77_decompress(bytes(rom), off)
    if dec is None:
        raise AssertionError(f'invalid Part 2 air mission title LZ77 block at 0x{off:X}')
    data, consumed = dec
    if len(data) != 64 * 32:
        raise AssertionError(f'unexpected Part 2 air mission title size at 0x{off:X}: {len(data)}')

    font_path = require_font(OKDANDAN_FONT, 'OkDanDan')

    canvas = Image.new('P', (128, 32), 0)
    text = '하늘의 적'
    for size in range(18, 8, -1):
        font = ImageFont.truetype(font_path, size)
        probe = ImageDraw.Draw(Image.new('L', (1, 1), 0))
        bbox = probe.textbbox((0, 0), text, font=font, stroke_width=1)
        if bbox[2] - bbox[0] <= 124 and bbox[3] - bbox[1] <= 24:
            break
    tw = bbox[2] - bbox[0]
    th = bbox[3] - bbox[1]
    x = (128 - tw) // 2 - bbox[0]
    y = (32 - th) // 2 - bbox[1] + 2

    stroke_mask = Image.new('L', (128, 32), 0)
    fill_mask = Image.new('L', (128, 32), 0)
    ImageDraw.Draw(stroke_mask).text((x, y), text, font=font, fill=255, stroke_width=1, stroke_fill=255)
    ImageDraw.Draw(fill_mask).text((x, y), text, font=font, fill=255)
    dst = canvas.load()
    stroke_px = stroke_mask.load()
    fill_px = fill_mask.load()
    for yy in range(32):
        for xx in range(128):
            if stroke_px[xx, yy]:
                dst[xx, yy] = 15
            if fill_px[xx, yy]:
                dst[xx, yy] = 10

    out = bytearray(len(data))
    px = canvas.load()
    for sprite in range(2):
        for ty in range(4):
            for tx in range(8):
                tile_idx = sprite * 32 + ty * 8 + tx
                sx = sprite * 64 + tx * 8
                sy = ty * 8
                base = tile_idx * 32
                for row in range(8):
                    for col in range(8):
                        value = px[sx + col, sy + row] & 0x0F
                        bi = base + row * 4 + col // 2
                        if col & 1:
                            out[bi] |= value << 4
                        else:
                            out[bi] |= value

    comp = lz77_compress_optimal(bytes(out), vram_safe=True)
    if len(comp) > consumed:
        raise AssertionError(f'Part 2 air mission title LZ77 overflow: {len(comp)} > {consumed}')
    rom[off:off + consumed] = comp + bytes(consumed - len(comp))
    return 1


def patch_part2_air_supremacy_title_obj(rom):
    """Redraw the Part 2 "Rule the sky" tutorial mission title OBJ sheet."""
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    from PIL import Image, ImageDraw, ImageFont
    from lz77_compress import lz77_compress_optimal
    from lz77_scan import lz77_decompress

    off = 0xC1205C
    dec = lz77_decompress(bytes(rom), off)
    if dec is None:
        raise AssertionError(f'invalid Part 2 air supremacy title LZ77 block at 0x{off:X}')
    data, consumed = dec
    if len(data) != 64 * 32:
        raise AssertionError(f'unexpected Part 2 air supremacy title size at 0x{off:X}: {len(data)}')

    text = '하늘 제패!'
    font_path = require_font(APPLE_SDGOTHIC_BOLD, 'Apple SD Gothic Neo')
    font_index = 6

    def load_title_font(size):
        if font_index is None:
            return ImageFont.truetype(font_path, size)
        return ImageFont.truetype(font_path, size, index=font_index)

    probe = ImageDraw.Draw(Image.new('L', (1, 1), 0))
    for size in range(24, 11, -1):
        font = load_title_font(size)
        bbox = probe.textbbox((0, 0), text, font=font, stroke_width=1)
        if bbox[2] - bbox[0] <= 124 and bbox[3] - bbox[1] <= 26:
            break

    tw = bbox[2] - bbox[0]
    th = bbox[3] - bbox[1]
    x = (128 - tw) // 2 - bbox[0]
    y = (32 - th) // 2 - bbox[1] + 1

    stroke_mask = Image.new('L', (128, 32), 0)
    fill_mask = Image.new('L', (128, 32), 0)
    ImageDraw.Draw(stroke_mask).text((x, y), text, font=font, fill=255, stroke_width=1, stroke_fill=255)
    ImageDraw.Draw(fill_mask).text((x, y), text, font=font, fill=255)

    canvas = Image.new('P', (128, 32), 0)
    dst = canvas.load()
    stroke_px = stroke_mask.load()
    fill_px = fill_mask.load()
    for yy in range(32):
        for xx in range(128):
            if stroke_px[xx, yy] >= 70:
                dst[xx, yy] = 14
            if fill_px[xx, yy] >= 190:
                dst[xx, yy] = 10

    out = bytearray(len(data))
    px = canvas.load()
    for sprite in range(2):
        for ty in range(4):
            for tx in range(8):
                tile_idx = sprite * 32 + ty * 8 + tx
                sx = sprite * 64 + tx * 8
                sy = ty * 8
                base = tile_idx * 32
                for row in range(8):
                    for col in range(8):
                        value = px[sx + col, sy + row] & 0x0F
                        bi = base + row * 4 + col // 2
                        if col & 1:
                            out[bi] |= value << 4
                        else:
                            out[bi] |= value

    comp = lz77_compress_optimal(bytes(out), vram_safe=True)
    if len(comp) > consumed:
        raise AssertionError(f'Part 2 air supremacy title LZ77 overflow: {len(comp)} > {consumed}')
    rom[off:off + consumed] = comp + bytes(consumed - len(comp))
    return 1


def patch_residual_ascii_labels(rom, syl_to_code, unmapped):
    """Replace fixed ASCII labels still used by map/menu text renderers."""
    replacements = {
        b'BLACK HOLE': '블랙홀',
        b'YELLOW COMET': '옐로코멧',
        b'YELLOW COMMET': '옐로코멧',
        b'GREEN EARTH': '그린어스',
        b'BLUE MOON': '블루문',
        b'RED STAR': '레드스타',
        b'NEUTRAL': '중립',
        b'HARD*CAMPAIGN': '하드캠페인',
        b'CAMPAIGN': '캠페인',
    }
    patched = 0
    for old, text in replacements.items():
        enc = encode_text(text, syl_to_code, unmapped)
        if len(enc) > len(old):
            raise AssertionError(f'residual ASCII replacement too long: {old!r} -> {text}')
        payload = enc + b'\x00' + bytes(max(0, len(old) - len(enc) - 1))
        pos = 0
        while True:
            idx = rom.find(old, pos)
            if idx < 0:
                break
            rom[idx:idx + len(old)] = payload[:len(old)]
            patched += 1
            pos = idx + len(old)
    return patched


