        enc = encode_text(text, syl_to_code, unmapped)
        if len(enc) > slot_len:
            raise AssertionError(f'zero-padded text overflow at 0x{faddr:X}: {len(enc)} > {slot_len}')
        rom[faddr:faddr + slot_len] = enc + bytes(slot_len - len(enc))

